void os_timeout_arm_set (TskTimeoutFunc tsk_timeout_func , void * tsk_timeout_arg)
{
  os_tsk_running->tsk_timeout_func     = tsk_timeout_func ;
  os_tsk_running->tsk_timeout_func_arg = tsk_timeout_arg  ; 
}

//--------------------------------------------------------------------------//

void os_timeout_arm_clr (void)
{
  os_tsk_running->tsk_timeout_func = 0 ;
}

